function processorSchemaFields(schema){
 let fields=[];
 const add=(value,path,required=false)=>{
  if(value&&typeof value==="object"&&!Array.isArray(value)&&value.properties&&typeof value.properties==="object"){
   let requiredNames=Array.isArray(value.required)?value.required:[];
   Object.entries(value.properties).forEach(([name,child])=>add(child,path?path+"."+name:name,requiredNames.includes(name)));
   return;
  }
  if(value&&typeof value==="object"&&!Array.isArray(value)&&!value.type&&!value.description&&!value.properties){
   Object.entries(value).forEach(([name,child])=>add(child,path?path+"."+name:name,false));
   return;
  }
  let type=value&&typeof value==="object"?value.type:typeof value==="string"?"string":"any";
  let description=value&&typeof value==="object"?value.description:typeof value==="string"?value:"";
  fields.push({path,type:type||"object",description:description||"",required:required||!!(value&&value.required)});
 };
 if(schema&&typeof schema==="object")add(schema,"");
 return fields;
}
