async function refreshNodes(){let request=++S.nodeRequest,page=S.nodePage,d=await api("/api/runs/"+S.run+"/nodes?page="+page+"&page_size=10");if(request!==S.nodeRequest)return;S.nodeTotalPages=d.total_pages||1;if(S.nodePage>S.nodeTotalPages){S.nodePage=S.nodeTotalPages;return refreshNodes()}$("#node-count").textContent=(d.total||0)+" 条";$("#nodes-page-label").textContent="第 "+S.nodePage+" / "+S.nodeTotalPages+" 页 · 共 "+(d.total||0)+" 条";$("#nodes-prev").disabled=S.nodePage<=1;$("#nodes-next").disabled=S.nodePage>=S.nodeTotalPages;let items=d.items||[];$("#node-timeline").innerHTML=items.map(n=>'<article class="timeline-item '+esc(n.status)+'"><div class="timeline-mark"></div><div class="timeline-head"><b>'+esc(n.name)+'</b>'+chip(n.status)+'</div><small>'+esc(nodeTypeName({type:n.type},S.nodes.builtins.concat(S.nodes.automation)))+' · '+fmt(n.started_at)+' · '+(n.duration_ms==null?"运行中":Math.floor(n.duration_ms/1000)+" 秒")+'</small>'+(n.logs?.length?'<pre class="log-box">'+n.logs.map(esc).join("\n")+'</pre>':"")+(n.error?'<div class="node-error">'+esc(n.error)+'</div>':"")+(n.screenshot_url?'<a class="screenshot-link" href="'+esc(n.screenshot_url)+'" target="_blank" rel="noreferrer">查看节点截图 ↗</a>':"")+'<details><summary>输入 / 输出</summary><pre>'+esc(JSON.stringify({input:n.input,output:n.output},null,2))+'</pre></details></article>').join("")||'<div class="empty-row">尚无节点执行记录。</div>'}
async function refreshNetwork(){let request=++S.networkRequest,page=S.networkPage,d=await api("/api/runs/"+S.run+"/network?page="+page+"&page_size=10");if(request!==S.networkRequest)return;S.networkTotalPages=d.total_pages||1;if(S.networkPage>S.networkTotalPages){S.networkPage=S.networkTotalPages;return refreshNetwork()}$("#network-count").textContent=(d.total||0)+" 条";$("#network-page-label").textContent="第 "+S.networkPage+" / "+S.networkTotalPages+" 页 · 共 "+(d.total||0)+" 条";$("#network-prev").disabled=S.networkPage<=1;$("#network-next").disabled=S.networkPage>=S.networkTotalPages;$("#network-events").innerHTML=(d.items||[]).map(n=>'<article class="network-event"><div class="network-event-head"><b>'+esc(n.method)+' '+esc(n.url)+'</b><span class="network-state '+esc(n.status)+'">'+(n.response_status?esc(n.response_status+" "+(n.response_status_text||"")):esc(n.status==="failed"?"请求失败":n.status==="pending"?"进行中":"已完成"))+'</span></div><small>'+esc(n.resource_type)+' · '+fmt(n.started_at)+(n.response_body_bytes==null?"":" · "+n.response_body_bytes+" B")+(n.failure?' · '+esc(n.failure):"")+'</small><details><summary>查看请求 / 响应数据</summary><div class="network-data-grid"><div><b>请求头</b><pre>'+esc(JSON.stringify(n.request_headers||{},null,2))+'</pre></div><div><b>请求体'+(n.request_body_truncated?'（已截断）':n.request_body_skipped?'（未保存：'+esc(n.request_body_skipped)+'）':'')+'</b><pre>'+esc(n.request_body||"")+'</pre></div><div><b>响应头</b><pre>'+esc(JSON.stringify(n.response_headers||{},null,2))+'</pre></div><div><b>响应体'+(n.response_body_truncated?'（已截断）':n.response_body_skipped?'（未保存：'+esc(n.response_body_skipped)+'）':'')+'</b><pre>'+esc(n.response_body||"")+'</pre></div></div></details></article>').join("")||'<div class="empty-row">等待页面产生网络请求…</div>'}
function setDetailTab(tab){S.detailTab=tab;let nodes=tab==="nodes";$("#tab-nodes").classList.toggle("active",nodes);$("#tab-nodes").setAttribute("aria-selected",String(nodes));$("#nodes-tab-panel").hidden=!nodes;$("#tab-network").classList.toggle("active",!nodes);$("#tab-network").setAttribute("aria-selected",String(!nodes));$("#network-tab-panel").hidden=nodes}
$("#tab-nodes").onclick=()=>{setDetailTab("nodes");refreshNodes().catch(e=>toast(e.message))};$("#tab-network").onclick=()=>{setDetailTab("network");refreshNetwork().catch(e=>toast(e.message))};$("#nodes-prev").onclick=()=>{if(S.nodePage>1){S.nodePage--;refreshNodes().catch(e=>toast(e.message))}};$("#nodes-next").onclick=()=>{if(S.nodePage<S.nodeTotalPages){S.nodePage++;refreshNodes().catch(e=>toast(e.message))}};$("#network-prev").onclick=()=>{if(S.networkPage>1){S.networkPage--;refreshNetwork().catch(e=>toast(e.message))}};$("#network-next").onclick=()=>{if(S.networkPage<S.networkTotalPages){S.networkPage++;refreshNetwork().catch(e=>toast(e.message))}}
function recordingNetworkHTML(n){return '<article class="network-event"><div class="network-event-head"><b>'+esc(n.method)+' '+esc(n.url)+'</b><span class="network-state '+esc(n.status)+'">'+(n.response_status?esc(n.response_status+' '+(n.response_status_text||'')):esc(n.status==='failed'?'请求失败':n.status==='pending'?'进行中':'已完成'))+'</span></div><small>'+esc(n.resource_type)+' · '+fmt(n.started_at)+(n.response_body_bytes==null?'':' · '+n.response_body_bytes+' B')+(n.failure?' · '+esc(n.failure):'')+'</small><details><summary>查看请求 / 响应数据</summary><div class="network-data-grid"><div><b>请求头</b><pre>'+esc(JSON.stringify(n.request_headers||{},null,2))+'</pre></div><div><b>请求体'+(n.request_body_truncated?'（已截断）':n.request_body_skipped?'（未保存：'+esc(n.request_body_skipped)+'）':'')+'</b><pre>'+esc(n.request_body||'')+'</pre></div><div><b>响应头</b><pre>'+esc(JSON.stringify(n.response_headers||{},null,2))+'</pre></div><div><b>响应体'+(n.response_body_truncated?'（已截断）':n.response_body_skipped?'（未保存：'+esc(n.response_body_skipped)+'）':'')+'</b><pre>'+esc(n.response_body||'')+'</pre></div></div></details></article>'}
async function refreshRecordings(){let records=await api('/api/recordings');S.recordings=records;let root=$('#recording-list');root.innerHTML=records.map(r=>'<article class="recording-row"><div class="recording-row-main"><b>'+esc(r.name||'未命名录制')+'</b><span>'+esc(r.task_name)+' · '+fmt(r.started_at)+'</span><small>'+r.action_count+' 次操作 · '+r.network_event_count+' 条网络请求 · '+(r.status==='saved'?'已保存':r.status==='recording'?'录制中':'待命名保存')+'</small></div><div class="recording-row-actions">'+(r.status==='saved'?'<button class="outline-button" data-recording-open="'+r.id+'">查看</button>':r.status==='draft'?'<button class="outline-button" data-recording-save="'+r.id+'">保存并命名</button>':'')+(r.status!=='recording'?'<button class="danger-text" data-recording-delete="'+r.id+'">删除</button>':'')+'</div></article>').join('')||'<div class="empty-row">还没有录制内容。解锁浏览器操作后可开启录制。</div>';root.querySelectorAll('[data-recording-open]').forEach(b=>b.onclick=()=>location.hash='#/recordings/'+b.dataset.recordingOpen);root.querySelectorAll('[data-recording-save]').forEach(b=>b.onclick=()=>openRecordingSave(+b.dataset.recordingSave));root.querySelectorAll('[data-recording-delete]').forEach(b=>b.onclick=()=>deleteRecording(+b.dataset.recordingDelete))}
function openRecordingSave(id){S.pendingRecordingId=id;$('#recording-name').value='';$('#record-save-dialog').showModal();$('#recording-name').focus()}
async function deleteRecording(id){if(!confirm('确定删除此录制内容及其截图吗？'))return;try{await api('/api/recordings/'+id,{method:'DELETE'});toast('录制内容已删除');await refreshRecordings()}catch(e){toast(e.message)}}
async function renderRecordingDetail(id){let r=await api('/api/recordings/'+id);S.recordingDetail=r;view('recording-detail');$('#recording-detail-title').textContent=r.name;$('#recording-detail-summary').textContent=r.task_name+' · '+fmt(r.started_at)+' 至 '+fmt(r.finished_at)+' · '+r.actions.length+' 次操作 · '+r.network_events.length+' 条网络请求';let names={mouse_down:'鼠标按下',mouse_up:'鼠标抬起',wheel:'滚动',key:'键盘操作',navigate:'页面跳转'};$('#recording-actions').innerHTML=r.actions.map(a=>'<article class="recording-action"><div class="recording-action-head"><b>'+String(a.sequence).padStart(2,'0')+' · '+esc(names[a.action]||a.action)+'</b><time>'+fmt(a.occurred_at)+'</time></div><pre>'+esc(JSON.stringify(a.details,null,2))+'</pre><a href="'+esc(a.screenshot_url)+'" target="_blank" rel="noreferrer"><img loading="lazy" src="'+esc(a.screenshot_url)+'" alt="操作 '+a.sequence+' 后的页面截图"></a></article>').join('')||'<div class="empty-row">本次录制没有操作截图。</div>';$('#recording-network-events').innerHTML=r.network_events.map(recordingNetworkHTML).join('')||'<div class="empty-row">录制期间没有捕获到网络请求。</div>'}
$('#open-recordings').onclick=()=>location.hash='#/recordings';$('#back-from-recordings').onclick=()=>location.hash='#/';$('#refresh-recordings').onclick=()=>refreshRecordings().catch(e=>toast(e.message));$('#back-from-recording-detail').onclick=()=>location.hash='#/recordings';
$('#record-save-form').onsubmit=async e=>{e.preventDefault();if(!S.pendingRecordingId)return;try{await api('/api/recordings/'+S.pendingRecordingId+'/save',{method:'POST',body:JSON.stringify({name:$('#recording-name').value.trim()})});$('#record-save-dialog').close();toast('录制内容已保存');S.pendingRecordingId=null;await refreshRecordings()}catch(err){toast(err.message)}};$('#record-save-later').onclick=()=>$('#record-save-dialog').close();$('#record-save-close').onclick=()=>$('#record-save-dialog').close();
async function runView(id){S.run=id;S.runTerminal=false;S.nodePage=1;S.networkPage=1;S.detailTab="nodes";setDetailTab("nodes");view("run");await renderRun();if(S.runTerminal)return;if(S.current?.browser_available)connect();else{$("#connection-overlay").textContent="此实例当前没有可用的浏览器标签页";$("#connection-overlay").hidden=false;conn("浏览器标签页不可用","error")}clearInterval(S.timer);if(!S.runTerminal)S.timer=setInterval(renderRun,1600)}
async function renderRun(){if(!S.run||S.refreshing)return;S.refreshing=true;try{let r=await api("/api/runs/"+S.run+"?include_nodes=false");S.current=r;await refreshDetails();$("#browser-run-title").textContent=r.task_name+" · 实例 #"+r.id+((r.definition_snapshot.device_mode||"desktop")==="mobile"?" · 移动设备":" · PC 桌面");$("#run-status-title").textContent=labels[r.status]||r.status;$("#run-summary").textContent="开始 "+fmt(r.started_at)+" · 节点 "+r.node_count+"/"+(r.max_node_executions||"—")+" · "+(r.current_node_name||"")+(r.current_node_elapsed_seconds==null?"":" · 已执行 "+r.current_node_elapsed_seconds+" 秒");$("#run-error").innerHTML=r.error?'<div class="error-callout"><b>运行出错</b><span>'+esc(r.error)+'</span></div>':"";$("#global-data").textContent=JSON.stringify(r.global_data||{},null,2);let active=["running","waiting_input","waiting_operation"].includes(r.status),pageAvailable=r.browser_available;$("#run-actions").innerHTML=(r.status==="error"?'<button class="outline-button" id="rerun">重新发起</button>':"")+(active?'<button class="danger-button" id="cancel">取消实例</button>':"");$("#cancel")?.addEventListener("click",async()=>{try{await api("/api/runs/"+r.id+"/cancel",{method:"POST"});toast("已取消");renderRun()}catch(e){toast(e.message)}});$("#rerun")?.addEventListener("click",async()=>{try{let d=prompt("启动数据 JSON 对象",JSON.stringify(r.start_data||{}));if(d===null)return;let x=await api("/api/runs/"+r.id+"/rerun",{method:"POST",body:JSON.stringify({data:JSON.parse(d)})});location.hash="#/runs/"+x.id}catch(e){toast(e.message)}});
if(!active){S.runTerminal=true;closeWs()}let node=(r.definition_snapshot.nodes||[]).find(n=>n.id===r.current_node_id),ha=$("#human-actions");ha.innerHTML=r.status==="waiting_operation"?'<button class="primary-button human-action-button" id="operated">已操作，继续</button>':r.status==="waiting_input"?'<button class="primary-button human-action-button" id="input-open">数据输入</button>':"";$("#operated")?.addEventListener("click",async()=>{try{await api("/api/runs/"+r.id+"/human-operation",{method:"POST"});toast("已提交，流程继续")}catch(e){toast(e.message)}});$("#input-open")?.addEventListener("click",()=>humanForm(r,node));
$("#capture-run").disabled=!pageAvailable;$("#run-address-form").hidden=!pageAvailable;$("#unlock-control").disabled=!pageAvailable||!S.ws||S.ws.readyState!==1;$("#capture-run").onclick=()=>{location.href="/api/runs/"+r.id+"/screenshot"}}catch(e){if(e.status===404){S.runTerminal=true;closeWs();$("#run-status-title").textContent="运行记录已删除";$("#run-actions").replaceChildren();conn("运行记录已删除","error")}toast(e.message)}finally{S.refreshing=false}}
function setPath(o,path,v){let p=path.replace(/\[(\d+)\]/g,".$1").split("."),c=o;for(let i=0;i<p.length;i++){let k=p[i],last=i===p.length-1;if(Array.isArray(c)){let n=Number(k);while(c.length<=n)c.push(null);if(last)c[n]=v;else c=c[n]??=(/^\d+$/.test(p[i+1])?[]:{})}else if(last)c[k]=v;else c=c[k]??=(/^\d+$/.test(p[i+1])?[]:{})}}
function humanForm(r,n){let fields=n?.config?.fields||[];$("#human-form-title").textContent=n?.name||"人工数据输入";$("#human-fields").innerHTML=fields.map((f,i)=>{let id="human-"+i;if(f.type==="boolean"||f.type==="select")return '<label class="field-label">'+esc(f.label||f.name)+(f.required?" *":"")+'<select data-path="'+esc(f.name)+'"><option value="">请选择</option>'+(f.type==="boolean"?'<option value="true">是</option><option value="false">否</option>':(f.options||[]).map(x=>'<option>'+esc(x)+'</option>').join(""))+'</select></label>';return '<label class="field-label">'+esc(f.label||f.name)+(f.required?" *":"")+'<input data-path="'+esc(f.name)+'" type="'+(f.type==="number"?"number":f.type==="date"?"date":"text")+'" '+(f.required?"required":"")+(f.min!=null?' min="'+f.min+'"':"")+(f.max!=null?' max="'+f.max+'"':"")+(f.min_length!=null?' minlength="'+f.min_length+'"':"")+(f.max_length!=null?' maxlength="'+f.max_length+'"':"")+'></label>'}).join("")||'<p class="form-note">没有定义字段，可提交空对象继续。</p>';$("#input-dialog").showModal()}
$("#human-form").onsubmit=async e=>{e.preventDefault();try{let d={};$("#human-fields").querySelectorAll("[data-path]").forEach(x=>{if(x.value==="")return;let v=x.type==="number"?Number(x.value):x.value;if(v==="true"||v==="false")v=v==="true";setPath(d,x.dataset.path,v)});await api("/api/runs/"+S.run+"/human-input",{method:"POST",body:JSON.stringify(d)});$("#input-dialog").close();toast("输入已保存")}catch(err){toast(err.fields?Object.values(err.fields).join("；"):err.message)}};
function conn(t,k){$("#connection-state").innerHTML="<i></i><span>"+esc(t)+"</span>";$("#connection-state").className="page-status "+(k||"")}
function showRecordingSave(id){if(!id||S.shownRecordingId===id)return;S.pendingRecordingId=id;S.shownRecordingId=id;$("#recording-name").value="";let dialog=$("#record-save-dialog");if(!dialog.open)dialog.showModal()}
function connect(){if(!S.run||S.runTerminal)return;closeWs();let proto=location.protocol==="https:"?"wss:":"ws:",ws=new WebSocket(proto+"//"+location.host+"/ws/runs/"+S.run);S.ws=ws;ws.binaryType="blob";ws.onopen=()=>{S.retry=700;conn("实时同步","online");$("#unlock-control").disabled=false};ws.onmessage=async e=>{if(typeof e.data!=="string"){let b=await createImageBitmap(e.data),c=$("#run-screen"),ctx=c.getContext("2d");c.width=b.width;c.height=b.height;ctx.drawImage(b,0,0);b.close();$("#connection-overlay").hidden=true;return}let m=JSON.parse(e.data);if(m.type==="status"&&m.url){$("#run-url").value=m.url==="about:blank"?"":m.url;$("#run-url-label").textContent=m.url}if(m.type==="control"){let wasRecording=S.recording,previousRecordingId=S.recordingId;S.controller=m.owned;S.recording=!!m.recording;if(m.recording_id)S.recordingId=m.recording_id;S.recordingCount=m.recording_count||0;$("#recording-count").textContent=String(S.recordingCount);$("#unlock-control").textContent=m.owned?(S.recording?"锁定并保存录制":"锁定操作"):m.locked?"其他人操作中":"解锁操作";$("#unlock-control").classList.toggle("active",m.owned);$("#recording-indicator").hidden=!S.recording;if(wasRecording&&!S.recording){let stoppedId=m.stopped_recording_id||previousRecordingId;if(stoppedId)showRecordingSave(stoppedId);S.recordingId=null}}if(m.type==="recording_started"){S.recording=true;S.recordingId=m.id;S.shownRecordingId=null;S.recordingCount=0;$("#recording-count").textContent="0";$("#recording-indicator").hidden=false;toast("录制已开始") }if(m.type==="recording_action"){S.recordingCount=m.sequence;$("#recording-count").textContent=String(m.sequence)}if(m.type==="recording_stopped"){S.recording=false;S.recordingId=null;$("#recording-indicator").hidden=true;showRecordingSave(m.id)}if(m.type==="error"){conn(m.message,"error");$("#connection-overlay").textContent=m.message;$("#connection-overlay").hidden=false}};ws.onclose=event=>{if(event.code===4000){S.runTerminal=true;closeWs();$("#unlock-control").disabled=true;conn("任务已结束","error");return}let interruptedRecordingId=S.recording?S.recordingId:null;S.controller=false;S.recording=false;S.recordingId=null;$("#recording-indicator").hidden=true;if(interruptedRecordingId)showRecordingSave(interruptedRecordingId);if(S.run&&!S.runTerminal){conn("连接已断开，正在重连…","error");$("#connection-overlay").textContent="连接已断开，正在重连…";$("#connection-overlay").hidden=false;$("#unlock-control").disabled=true;S.reconnectTimer=setTimeout(()=>S.run&&!S.runTerminal&&connect(),S.retry||700);S.retry=Math.min((S.retry||700)*2,8000)}};ws.onerror=()=>ws.close()}
function closeWs(){clearInterval(S.timer);S.timer=null;clearTimeout(S.reconnectTimer);S.reconnectTimer=null;if(S.ws){S.ws.onclose=null;S.ws.close();S.ws=null}}
$("#unlock-control").onclick=()=>{if(!S.ws)return;if(S.controller){S.ws.send(JSON.stringify({action:"lock"}));return}let record=confirm("是否打开录制功能？开启后会记录操作、每次操作后的截图和录制期间的网络请求。");S.ws.send(JSON.stringify({action:"unlock",record}))};$("#run-address-form").onsubmit=e=>{e.preventDefault();S.ws?.send(JSON.stringify({action:"navigate",url:$("#run-url").value}))};
const runViewport=$("#run-viewport"),fullscreenButton=$("#toggle-run-fullscreen");function syncRunFullscreen(){let active=document.fullscreenElement===runViewport;fullscreenButton.setAttribute("aria-label",active?"退出全屏":"进入全屏");fullscreenButton.title=active?"退出全屏":"全屏"}fullscreenButton.onclick=async()=>{try{if(document.fullscreenElement===runViewport)await document.exitFullscreen();else await runViewport.requestFullscreen()}catch(e){toast("当前浏览器无法切换全屏")}};document.addEventListener("fullscreenchange",syncRunFullscreen);
function xy(e){let c=$("#run-screen"),r=c.getBoundingClientRect(),s=Math.min(r.width/c.width,r.height/c.height);return{x:(e.clientX-r.left-(r.width-c.width*s)/2)/s,y:(e.clientY-r.top-(r.height-c.height*s)/2)/s}}
let can=$("#run-screen");can.onpointerdown=e=>{can.focus();if(S.controller)S.ws?.send(JSON.stringify(Object.assign({action:"mouse_down",button:e.button===2?"right":"left"},xy(e))))};can.onpointerup=e=>{if(S.controller)S.ws?.send(JSON.stringify(Object.assign({action:"mouse_up",button:e.button===2?"right":"left"},xy(e))))};can.onpointermove=e=>{if(!S.controller||performance.now()-(S.pointerAt||0)<40)return;S.pointerAt=performance.now();S.ws?.send(JSON.stringify(Object.assign({action:"move"},xy(e))))};can.onwheel=e=>{e.preventDefault();if(S.controller)S.ws?.send(JSON.stringify({action:"wheel",deltaX:e.deltaX,deltaY:e.deltaY}))};can.oncontextmenu=e=>e.preventDefault();can.onkeydown=e=>{if(S.controller){let k=[];if(e.ctrlKey)k.push("Control");if(e.altKey)k.push("Alt");if(e.shiftKey)k.push("Shift");if(e.metaKey)k.push("Meta");k.push(e.key);S.ws?.send(JSON.stringify({action:"key",key:k.join("+")}));if([" ","Backspace","Tab"].includes(e.key)||e.key.startsWith("Arrow"))e.preventDefault()}};
async function route(){clearInterval(S.timer);let m=location.hash.match(/^#\/runs\/(\d+)$/),recording=location.hash.match(/^#\/recordings\/(\d+)$/);if(m){await runView(+m[1])}else if(recording){closeWs();S.run=null;try{await renderRecordingDetail(+recording[1])}catch(e){toast(e.message);location.hash="#/recordings"}}else if(location.hash==="#/recordings"){closeWs();S.run=null;view("recordings");await refreshRecordings().catch(e=>toast(e.message))}else{closeWs();S.run=null;view("dash");refresh();S.timer=setInterval(refresh,4000)}}window.onhashchange=route;
async function init(){try{S.nodes=await api("/api/nodes");await route()}catch(e){toast(e.message)}}init();








